server {
    listen 8080;
    root /usr/share/nginx/html;
    index index.html;

    # Hashed asset bundles — immutable caching
    location /assets/ {
        add_header Cache-Control "public, max-age=31536000, immutable";
    }

    # index.html must never be cached so new deploys are picked up immediately
    location = /index.html {
        add_header Cache-Control "no-cache";
    }

    # Proxy API calls to the API container
    location /api/ {
        proxy_pass         http://api:8080;
        proxy_set_header   Host              $host;
        proxy_set_header   X-Real-IP         $remote_addr;
        proxy_set_header   X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header   X-Forwarded-Proto $scheme;
    }

    # Proxy Google OAuth callback so the redirect URI is the nginx origin
    location /signin-google {
        proxy_pass         http://api:8080;
        proxy_set_header   Host              $host;
        proxy_set_header   X-Real-IP         $remote_addr;
        proxy_set_header   X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header   X-Forwarded-Proto $scheme;
    }

    # Health endpoints
    location /health/ {
        proxy_pass         http://api:8080;
    }

    # SPA fallback — all unmatched paths return index.html for React Router
    location / {
        try_files $uri $uri/ /index.html;
    }
}

